// stores/kycStore.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { kycService } from '../services/kycService';

export interface KycRequest {
  id: string;
  userId: string;
  userName: string;
  userEmail: string;
  documentType: 'CNI' | 'PASSPORT';
  documentImage: string;
  selfieImage: string;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  submittedAt: Date;
  reviewedAt?: Date;
  rejectionReason?: string;
}

interface KycStore {
  requests: KycRequest[];
  isLoading: boolean;
  selectedRequest: KycRequest | null;

  // Actions
  fetchRequests: (filters?: { status?: string }) => Promise<void>;
  selectRequest: (id: string) => void;
  approveRequest: (id: string) => Promise<void>;
  rejectRequest: (id: string, reason: string) => Promise<void>;
  clearSelection: () => void;
}

export const useKycStore = create<KycStore>((set, get) => ({
  requests: [],
  isLoading: false,
  selectedRequest: null,

  fetchRequests: async (filters) => {
    set({ isLoading: true });
    try {
      const requests = await kycService.getRequests(filters);
      set({ requests });
    } catch (error) {
      console.error('Erreur lors du chargement des demandes KYC', error);
    } finally {
      set({ isLoading: false });
    }
  },

  selectRequest: (id) => {
    const request = get().requests.find(r => r.id === id);
    set({ selectedRequest: request || null });
  },

  approveRequest: async (id) => {
    try {
      await kycService.approveRequest(id);
      set((state) => ({
        requests: state.requests.map(req =>
          req.id === id
            ? { ...req, status: 'APPROVED', reviewedAt: new Date() }
            : req
        ),
      }));
    } catch (error) {
      console.error('Erreur lors de l\'approbation KYC', error);
      throw error;
    }
  },

  rejectRequest: async (id, reason) => {
    try {
      await kycService.rejectRequest(id, reason);
      set((state) => ({
        requests: state.requests.map(req =>
          req.id === id
            ? { ...req, status: 'REJECTED', reviewedAt: new Date(), rejectionReason: reason }
            : req
        ),
      }));
    } catch (error) {
      console.error('Erreur lors du rejet KYC', error);
      throw error;
    }
  },

  clearSelection: () => {
    set({ selectedRequest: null });
  },
}));
```

