import api from './api';

export interface KycFilters {
  status?: 'PENDING' | 'APPROVED' | 'REJECTED';
  search?: string;
}

class KycService {
  // Charger la liste des demandes KYC
  async getRequests(filters?: KycFilters): Promise<KycRequest[]> {
    const response = await api.get('/assistant/kyc', { params: filters });
    return response.data;
  }

  // Charger une demande KYC spécifique
  async getRequestById(id: string): Promise<KycRequest> {
    const response = await api.get(`/assistant/kyc/${id}`);
    return response.data;
  }

  // Approuver une demande KYC
  async approveRequest(id: string): Promise<void> {
    await api.put(`/assistant/kyc/${id}/approve`);
  }

  // Rejeter une demande KYC
  async rejectRequest(id: string, reason: string): Promise<void> {
    await api.put(`/assistant/kyc/${id}/reject`, { reason });
  }

  // Obtenir les statistiques KYC
  async getKycStats(): Promise<{
    pending: number;
    approved: number;
    rejected: number;
    total: number;
  }> {
    const response = await api.get('/assistant/kyc/stats');
    return response.data;
  }
}

export const kycService = new KycService();
