const RejectModal = ({ visible, onClose, onConfirm }) => {
  const [reason, setReason] = useState('');
  const [suggestedReasons] = useState([
    'Produit contrefait',
    'Images non conformes',
    'Prix trop élevé',
    'Description trompeuse',
    'Produit interdit',
    'Autre...',
  ]);

  return (
    <Modal visible={visible}>
      <Text>Sélectionnez ou saisissez un motif :</Text>
