@Get('assistant/kyc/:id/document')
@UseGuards(RolesGuard)
@Roles('assistant', 'admin')
async getDocumentUrl(@Param('id') id: string) {
  const kyc = await this.kycService.findOne(id);
  // Vérifier que l'assistant est autorisé
  // Générer une URL signée avec expiration de 5 minutes
