// Supprimer les documents lorsque l'utilisateur ferme son compte
async deleteUserKyc(userId: string) {
  // 1. Récupérer tous les documents de l'utilisateur
  const documents = await this.kycRepo.find({ where: { userId } });

  // 2. Supprimer les fichiers du stockage
  for (const doc of documents) {
    await this.storageService.deleteFile(doc.documentKey);
    await this.storageService.deleteFile(doc.selfieKey);
  }

  // 3. Supprimer les métadonnées (ou anonymiser)
  await this.kycRepo.softDelete({ userId });

  // 4. Logger la suppression
  await this.logService.log({
    action: 'KYC_DELETED',
    userId,
    timestamp: new Date(),
  });
}
